import{_ as e,o as l,c as n,ag as i}from"./chunks/framework.B45avKwg.js";const f=JSON.parse('{"title":"GenSense Rule Catalog","description":"","frontmatter":{},"headers":[],"relativePath":"rules.md","filePath":"rules.md"}'),a={name:"rules.md"};function d(s,t,r,o,c,g){return l(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="gensense-rule-catalog" tabindex="-1">GenSense Rule Catalog <a class="header-anchor" href="#gensense-rule-catalog" aria-label="Permalink to &quot;GenSense Rule Catalog&quot;">​</a></h1><p>This catalog lists all semantic rules currently active in the GenSense engine.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Rule ID</th><th style="text-align:left;">Severity</th><th style="text-align:left;">Category</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>RUST_ASYNC_MUTEX_DEADLOCK</code></td><td style="text-align:left;">Critical</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Holding a standard Mutex guard across an await point can block the entire executor thread.</td></tr><tr><td style="text-align:left;"><code>RUST_ASYNC_BLOCKING_IO</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Performance</td><td style="text-align:left;">Calling synchronous blocking functions inside an async task blocks the entire executor thread, stalling all other tasks on that thread.</td></tr><tr><td style="text-align:left;"><code>RUST_ASYNC_PANIC_PREVENTION</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Safety</td><td style="text-align:left;">Unwrapped Result or Option in async context can lead to unhandled task failures and cascading system instability.</td></tr><tr><td style="text-align:left;"><code>RUST_ASYNC_MISSING_TIMEOUT</code></td><td style="text-align:left;">Critical</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">A network or I/O call that never responds can hang an entire worker task indefinitely, leading to protocol-level stalls or cascading failures.</td></tr><tr><td style="text-align:left;"><code>RUST_MISSING_TRACING_SPAN</code></td><td style="text-align:left;">Info</td><td style="text-align:left;">Observability</td><td style="text-align:left;">Production-grade protocol logic must be visible in telemetry. Missing spans make debugging distributed hangs or latency spikes extremely difficult.</td></tr><tr><td style="text-align:left;"><code>RUST_FAKE_ASYNC</code></td><td style="text-align:left;">Info</td><td style="text-align:left;">Performance</td><td style="text-align:left;">Async functions without awaits introduce state machine overhead and return a future unnecessarily without concurrency benefits.</td></tr><tr><td style="text-align:left;"><code>JUMIA_GOD_SERVICE</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Architecture</td><td style="text-align:left;">Oversized services often contain mixed concerns, making them harder to test and maintain.</td></tr><tr><td style="text-align:left;"><code>JUMIA_REPETITIVE_DECIMAL_LOGIC</code></td><td style="text-align:left;">Info</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Scattered financial rounding/formatting logic can lead to inconsistent precision across the platform.</td></tr><tr><td style="text-align:left;"><code>JUMIA_STUB_FALLBACK</code></td><td style="text-align:left;">Info</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">While good for resilience, heavy reliance on fallback paths indicates the system is not running in its optimal high-performance mode.</td></tr><tr><td style="text-align:left;"><code>JUMIA_NESTING_LIMIT</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Deeply nested code is hard to read and often hide complex edge cases.</td></tr><tr><td style="text-align:left;"><code>JUMIA_ASYNC_FOR_EACH</code></td><td style="text-align:left;">Critical</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Array.forEach does not await promises. This leads to race conditions and unhandled rejections in production.</td></tr><tr><td style="text-align:left;"><code>SOL_STATE_MUTATION_CHECK</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Gas_Optimization</td><td style="text-align:left;">State mutations in read-only functions can sometimes cause transaction reverts or unexpected gas costs.</td></tr><tr><td style="text-align:left;"><code>SOL_SELFDESTRUCT_ADVISORY</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Contract destruction is a high-impact event that can sometimes lock funds or break integrations for users.</td></tr><tr><td style="text-align:left;"><code>SOL_PRAGMA_STABILITY</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Stability</td><td style="text-align:left;">Floating pragmas can lead to non-deterministic builds if different compiler versions are used across environments.</td></tr><tr><td style="text-align:left;"><code>SOL_ACCESS_CONTROL_SETTER</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Publicly accessible setters can allow unauthorized users to modify critical protocol parameters.</td></tr><tr><td style="text-align:left;"><code>SOL_ZERO_ADDRESS_CHECK</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Setting critical parameters to the zero address can accidentally &#39;brick&#39; contract functionality.</td></tr><tr><td style="text-align:left;"><code>SOL_MISSING_EVENT_INDEX</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Missing &#39;indexed&#39; attributes on critical event parameters (like addresses) makes it difficult to filter and search for events off-chain.</td></tr><tr><td style="text-align:left;"><code>SOL_HARDCODED_ADDRESS</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Hardcoding addresses (other than the zero address) makes the contract inflexible and prone to errors during multi-chain deployment or upgrades.</td></tr><tr><td style="text-align:left;"><code>SOL_TX_ORIGIN</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Using &#39;tx.origin&#39; makes the contract vulnerable to phishing-style reentrancy attacks. An attacker can trick a user into calling a malicious contract that then calls your contract.</td></tr><tr><td style="text-align:left;"><code>SOL_TIMESTAMP_DEPENDENCY</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Block timestamps can be slightly manipulated by miners, which might be risky if relied upon for critical logic like randomness.</td></tr><tr><td style="text-align:left;"><code>SOL_REENTRANCY_RISK</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">External calls (like &#39;.call{value: ...}&#39;) can trigger fallback functions, leading to reentrancy vulnerabilities if not properly protected.</td></tr><tr><td style="text-align:left;"><code>SOL_PRECISION_LOSS</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Fintech</td><td style="text-align:left;">In Solidity, integer division truncates. Dividing before multiplying can lead to significant precision loss in financial calculations.</td></tr><tr><td style="text-align:left;"><code>SOL_INTEGER_OVERFLOW</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Unchecked arithmetic can lead to silent integer overflows or underflows if the developer hasn&#39;t manually verified the safety of the operation. Modern Solidity (&gt;=0.8.0) handles this by default; &#39;unchecked&#39; blocks bypass this protection.</td></tr><tr><td style="text-align:left;"><code>SOL_MISSING_ACCESS_CONTROL</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Public or external functions that are missing access control modifiers can be executed by anyone, potentially allowing unauthorized state changes or fund drainage.</td></tr><tr><td style="text-align:left;"><code>RUST_GOD_FUNCTION</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Standardized Standard #2: Oversized functions indicate mixed concerns and low readability.</td></tr><tr><td style="text-align:left;"><code>RUST_NESTING_LIMIT</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Rule #vibecoding: Extreme indentation indicates complex, unmaintainable logic.</td></tr><tr><td style="text-align:left;"><code>TS_GOD_FUNCTION</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Standardized Standard #2: Oversized functions indicate mixed concerns.</td></tr><tr><td style="text-align:left;"><code>TS_NESTING_LIMIT</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Rule #vibecoding: Extreme indentation indicates complex logic.</td></tr><tr><td style="text-align:left;"><code>RUST_UNSAFE_BLOCK</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Unsafe code bypasses Rust&#39;s safety guarantees, which can sometimes lead to tricky undefined behavior if not audited.</td></tr><tr><td style="text-align:left;"><code>RUST_HOST_INTERACTION</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Isolation</td><td style="text-align:left;">Isolated workers are designed to be environment-agnostic; host interaction can break portability and security boundaries.</td></tr><tr><td style="text-align:left;"><code>RUST_STD_OUTPUT</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Direct standard output from libraries can interfere with the host application&#39;s logging strategy.</td></tr><tr><td style="text-align:left;"><code>RUST_ALLOCATION_IN_LOG</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Performance</td><td style="text-align:left;">This can cause unnecessary allocations even when the specific log level is disabled at runtime.</td></tr><tr><td style="text-align:left;"><code>RUST_CLONE_IN_LOOP</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Performance</td><td style="text-align:left;">Allocating memory repeatedly inside a loop can quietly degrade performance.</td></tr><tr><td style="text-align:left;"><code>RUST_CONSTRUCTOR_BLOAT</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Maintainability</td><td style="text-align:left;">Constructors with many arguments can be tricky to read and maintain.</td></tr><tr><td style="text-align:left;"><code>RUST_SILENT_FAILURE</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Logging a failure without propagating it or changing the system state is an anti-pattern that hides errors and breaks expected control flow.</td></tr><tr><td style="text-align:left;"><code>RUST_VEC_FRONT_REMOVE</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Performance</td><td style="text-align:left;">Removing from the front of a Vec requires shifting all subsequent elements, resulting in O(n) time complexity. This can cause significant latency in large collections.</td></tr><tr><td style="text-align:left;"><code>RUST_ALGO_N2_LOOP</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Performance</td><td style="text-align:left;">This pattern results in O(N²) algorithmic complexity, which can lead to exponential performance degradation as data size grows.</td></tr><tr><td style="text-align:left;"><code>RUST_CHANNEL_UNBOUNDED</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Concurrency</td><td style="text-align:left;">Unbounded channels can grow indefinitely if the consumer is slower than the producer, leading to Out-Of-Memory (OOM) crashes.</td></tr><tr><td style="text-align:left;"><code>RUST_OVER_GENERAL_VARIABLE</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Names like &#39;info&#39;, &#39;data&#39;, or &#39;item&#39; are hallmark AI scaffolding and hide the semantic intent of the data.</td></tr><tr><td style="text-align:left;"><code>RUST_LOCK_IO</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Performance</td><td style="text-align:left;">Holding locks during async I/O can cause lock contention and stall other tasks waiting for the same lock.</td></tr><tr><td style="text-align:left;"><code>RUST_UNCHECKED_IO</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">I/O operations (like opening files or network requests) are prone to failure. Unwrapping them can cause the entire service to panic.</td></tr><tr><td style="text-align:left;"><code>RUST_UNWRAP_SAFETY</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Unwrapping without documented justification is a production risk. If the assumption is wrong, the service will panic.</td></tr><tr><td style="text-align:left;"><code>RUST_TOKIO_SELECT_ELSE</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Select blocks without a default branch can hang indefinitely if all futures are pending or completed.</td></tr><tr><td style="text-align:left;"><code>RUST_LARGE_STACK_ALLOCATION</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Allocating large buffers (&gt;10KB) on the stack increases the risk of stack overflow, especially in async contexts with many concurrent tasks.</td></tr><tr><td style="text-align:left;"><code>RUST_PANIC_IN_LIB</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Safety</td><td style="text-align:left;">Unconditional panics in library or protocol crates cause hard crashes for consumers. Standard practice is to return &#39;Result&#39; and let the caller decide how to handle failure.</td></tr><tr><td style="text-align:left;"><code>SECRET_LEAK_DETECTION</code></td><td style="text-align:left;">Critical</td><td style="text-align:left;">Security</td><td style="text-align:left;">Hardcoding secrets (API keys, private keys, etc.) in source code is a major security risk and can lead to unauthorized access.</td></tr><tr><td style="text-align:left;"><code>TS_PRISMA_SELECT_STAR</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Performance</td><td style="text-align:left;">Fetching entire database rows (SELECT *) increases network overhead and can leak sensitive fields (e.g. password_hash).</td></tr><tr><td style="text-align:left;"><code>TS_HARDCODED_ENV_URL</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Hardcoded environment URLs prevent infrastructure portability and leak environment topology.</td></tr><tr><td style="text-align:left;"><code>JS_DYNAMIC_EXECUTION</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Dynamic execution can introduce unpredictability and increase the surface area for logic vulnerabilities in isolate environments.</td></tr><tr><td style="text-align:left;"><code>TS_DYNAMIC_EXECUTION</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Dynamic execution can introduce unpredictability and increase the surface area for logic vulnerabilities in isolate environments.</td></tr><tr><td style="text-align:left;"><code>TS_ALIASED_DYNAMIC_EXECUTION</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Aliasing &#39;eval&#39; to another variable can be used to bypass static analysis and execute arbitrary code dynamically.</td></tr><tr><td style="text-align:left;"><code>TS_CONSOLE_USAGE</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Direct console outputs can be tricky to filter in production logs.</td></tr><tr><td style="text-align:left;"><code>TS_BLOCKING_IO</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Performance</td><td style="text-align:left;">Synchronous calls block the event loop, which can significantly reduce the responsiveness of the service under load.</td></tr><tr><td style="text-align:left;"><code>TS_EMPTY_CATCH</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Silently swallowing errors makes debugging very difficult and can leave the app in a weird state.</td></tr><tr><td style="text-align:left;"><code>TS_NON_NULL_ASSERTION</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Non-null assertions bypass TypeScript&#39;s safety checks and can lead to runtime &#39;TypeError: Cannot read property of null&#39; errors.</td></tr><tr><td style="text-align:left;"><code>TS_MAGIC_NUMBER</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Maintainability</td><td style="text-align:left;">Magic numbers make code harder to read and maintain as their intent is not immediately clear.</td></tr><tr><td style="text-align:left;"><code>TS_ANY_TYPE</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Using &#39;any&#39; completely disables TypeScript&#39;s safety checks for that variable.</td></tr><tr><td style="text-align:left;"><code>TS_REACT_HOOK_DEPS</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Quality</td><td style="text-align:left;">Empty dependency arrays can cause stale closures if the hook references variables from the component scope.</td></tr><tr><td style="text-align:left;"><code>TS_BUNDLE_BLOAT</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Performance</td><td style="text-align:left;">Importing entire libraries (like lodash) can significantly bloat Next.js client-side bundles.</td></tr><tr><td style="text-align:left;"><code>TS_ASYNC_FOR_EACH</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Array.prototype.forEach is not promise-aware. The loop will continue without awaiting the callback, leading to race conditions and unhandled rejections.</td></tr><tr><td style="text-align:left;"><code>TS_SENSITIVE_DATA_LOGGING</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Logging sensitive credentials or PII in production logs is a major security violation and can lead to account takeovers.</td></tr><tr><td style="text-align:left;"><code>TS_DATA_LEAK_TRACKER</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Security</td><td style="text-align:left;">Data flow analysis confirms that sensitive input (e.g. passwords) is reaching a logging sink through intermediate variables.</td></tr><tr><td style="text-align:left;"><code>TS_FLOATING_PROMISE</code></td><td style="text-align:left;">Warning</td><td style="text-align:left;">Reliability</td><td style="text-align:left;">Floating promises can lead to race conditions, unhandled rejections, and non-deterministic behavior.</td></tr></tbody></table>',3)])])}const x=e(a,[["render",d]]);export{f as __pageData,x as default};
